"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["86994"],{18392(s){s.exports=JSON.parse('{"id":"FIN-1139","slug":"issued-shares","term":"Issued Shares","also_known_as":[],"difficulty":"Advanced","definition":"Issued shares are the shares a company has actually sold or given to shareholders, including any it has later bought back and holds in treasury.","explanation":["Issued shares sit between authorized shares and outstanding shares. Authorized shares are the maximum the company may issue. Issued shares are those it has actually issued. Outstanding shares are issued shares minus any treasury shares the company has bought back and still holds.","For example, a company with 60,000,000 issued shares that holds 5,000,000 in treasury has 55,000,000 shares outstanding.","The difference matters for calculations. Earnings per share, market capitalization and voting rights are based on outstanding shares, since treasury shares do not receive dividends or vote.","The number of issued shares changes when the company sells new shares, issues shares to employees, converts securities such as convertible bonds into shares or cancels shares it has bought back. Many companies cancel repurchased shares rather than holding them in treasury, which reduces issued shares directly."],"note":"","total":1500,"prev":{"slug":"iron-condor","term":"Iron Condor"},"next":{"slug":"issuer","term":"Issuer"}}')}}]);